insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r10-v1','0.1.0','Streetlights: cause, contrast and result','reading','guided_practice','Read the passage. Choose the correct letter, A, B, C or D, for each question.','Find the linking word (because, however, as a result, although, if) and decide what it connects before you choose.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Why did the town replace its streetlights?", "accepted_answers": ["B"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  Because residents complained about them"}, {"value": "B", "label": "B  To reduce the cost of electricity"}, {"value": "C", "label": "C  To reduce the number of road closures"}, {"value": "D", "label": "D  Because the orange lamps were too bright"}]}, {"id": "q2", "prompt": "What happened because residents complained?", "accepted_answers": ["C"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  The council removed the LED lamps"}, {"value": "B", "label": "B  Electricity costs doubled"}, {"value": "C", "label": "C  Shields were fitted and the lamps were dimmed at night"}, {"value": "D", "label": "D  Workers replaced the lamps more often"}]}, {"id": "q3", "prompt": "What does the sentence beginning “Although” show?", "accepted_answers": ["A"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  The changes cost some savings but reduced complaints"}, {"value": "B", "label": "B  The changes increased the savings"}, {"value": "C", "label": "C  The changes caused more complaints"}, {"value": "D", "label": "D  The changes were made before the new lamps arrived"}]}, {"id": "q4", "prompt": "Why do fewer roads have to be closed for repairs?", "accepted_answers": ["D"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  The lamps are dimmed after midnight"}, {"value": "B", "label": "B  Residents complain less"}, {"value": "C", "label": "C  The council has fewer workers"}, {"value": "D", "label": "D  The LED lamps last longer"}]}, {"id": "q5", "prompt": "According to the council, what would have happened if the lamps had not been dimmed?", "accepted_answers": ["A"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  The savings would have been higher"}, {"value": "B", "label": "B  More lamps would have broken"}, {"value": "C", "label": "C  Complaints would have fallen faster"}, {"value": "D", "label": "D  Roads would have been closed less often"}]}, {"id": "q6", "prompt": "What does “As a result” introduce?", "accepted_answers": ["B"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  A contrast with the previous sentence"}, {"value": "B", "label": "B  A consequence of the complaints"}, {"value": "C", "label": "C  An example of the savings"}, {"value": "D", "label": "D  A condition for the change"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Ten years ago, the town of Marlow Bridge replaced its old orange streetlights with white LED lamps. The main reason was cost: the new lamps use about half as much electricity. However, the change was not popular at first. Many residents said the white light was too harsh, and some complained that it kept them awake. As a result, the council fitted shields to lamps near bedroom windows and lowered their brightness after midnight. Although these changes reduced the savings slightly, complaints fell sharply. The council also found an unexpected benefit. Because the LED lamps last much longer, workers now replace them every twelve years instead of every four, so fewer roads have to be closed for repairs. If the lamps had not been dimmed, the council estimates that savings would have been ten per cent higher.", "teacher_notes": "1 B — “The main reason was cost” (A is a later effect, not the reason).\n2 C — “As a result, the council fitted shields … and lowered their brightness”.\n3 A — concession: a small loss of savings, a large fall in complaints.\n4 D — “Because the LED lamps last much longer … so fewer roads”.\n5 A — third conditional: savings would have been ten per cent higher.\n6 B — “As a result” follows the complaints.\nTeach: underline each linking word and draw an arrow from cause to effect.", "focus": "Recognise logical relationships: cause, result, contrast, concession and condition signalled by linking words."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'6d95b95299e6ed78739c3328c6a4bc730193ef9736cd4c8b7e2c8250c1d34e4a',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r11-v1','0.1.0','Late library: why, despite and if','reading','independent_check','Read the passage. Choose the correct letter, A, B, C or D, for each question. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Find the linking word (because, however, as a result, although, if) and decide what it connects before you choose.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Why did the library start opening late?", "accepted_answers": ["C"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  Security staff asked for longer hours"}, {"value": "B", "label": "B  Borrowing of books had fallen"}, {"value": "C", "label": "C  Many adults could not visit during the day because of work"}, {"value": "D", "label": "D  Children needed reading clubs"}]}, {"id": "q2", "prompt": "Why was extending the hours expensive?", "accepted_answers": ["B"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  More books had to be bought"}, {"value": "B", "label": "B  Extra security staff were needed"}, {"value": "C", "label": "C  The building needed more heating"}, {"value": "D", "label": "D  Volunteers had to be paid"}]}, {"id": "q3", "prompt": "What does “Nevertheless” show?", "accepted_answers": ["A"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  The library continued with the change despite the cost"}, {"value": "B", "label": "B  The cost was lower than expected"}, {"value": "C", "label": "C  The survey had been wrong"}, {"value": "D", "label": "D  Evening visits fell"}]}, {"id": "q4", "prompt": "What was one result of the late opening?", "accepted_answers": ["D"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  Weekend reading clubs began"}, {"value": "B", "label": "B  Security costs fell"}, {"value": "C", "label": "C  Friday visits rose"}, {"value": "D", "label": "D  Borrowing of study books increased"}]}, {"id": "q5", "prompt": "Why was the Friday late opening cancelled?", "accepted_answers": ["A"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  Very few people came"}, {"value": "B", "label": "B  Security staff were not available"}, {"value": "C", "label": "C  The volunteers left"}, {"value": "D", "label": "D  The survey recommended it"}]}, {"id": "q6", "prompt": "The weekend reading clubs will start only if …", "accepted_answers": ["C"], "taxonomy_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "supporting_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "options": [{"value": "A", "label": "A  Friday visits increase"}, {"value": "B", "label": "B  the council pays more"}, {"value": "C", "label": "C  enough volunteers are found"}, {"value": "D", "label": "D  adults ask for them"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Last year, a public library in a coastal city began opening until 10 p.m. on weekdays. The decision followed a survey which showed that many adults could not visit during the day because of work. Extending the hours was expensive, since extra security staff had to be employed. Nevertheless, the library judged the change worthwhile. Evening visits rose steadily, and borrowing of study books increased by a third. Despite this success, the late opening on Fridays was cancelled after six months because very few people came. The library now plans to use the Friday budget for weekend reading clubs for children, provided that enough volunteers can be found.", "teacher_notes": "1 C — “because of work”.\n2 B — “since extra security staff had to be employed”.\n3 A — “Nevertheless” = despite the expense.\n4 D — “borrowing of study books increased by a third”.\n5 A — “because very few people came”.\n6 C — “provided that enough volunteers can be found”.\nDifferent text from R10; not a calibrated equivalent form.", "focus": "Recognise logical relationships: cause, result, contrast, concession and condition signalled by linking words."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'2104a9e003938ac61780f705b419a9741648cbffb2bcaa3c52bf3313ef998c79',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r12-v1','0.1.0','Honeybees: what does it refer to?','reading','guided_practice','Read the passage. Choose the correct letter, A, B, C or D, for each question.','Look back to the nearest noun or idea that makes sense in place of the word, then check by replacing the word with your answer.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "In “several causes for this”, “this” refers to …", "accepted_answers": ["A"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the loss of honeybees each winter"}, {"value": "B", "label": "B  the work of scientists"}, {"value": "C", "label": "C  a tiny parasite"}, {"value": "D", "label": "D  the cold weather"}]}, {"id": "q2", "prompt": "In “attaches itself to bees”, “itself” refers to …", "accepted_answers": ["B"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the bee"}, {"value": "B", "label": "B  the parasite"}, {"value": "C", "label": "C  the scientist"}, {"value": "D", "label": "D  the flower"}]}, {"id": "q3", "prompt": "In “which means bees have fewer sources of food”, “which” refers to …", "accepted_answers": ["C"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the parasite"}, {"value": "B", "label": "B  the winter"}, {"value": "C", "label": "C  the loss of wild flowers"}, {"value": "D", "label": "D  the beekeepers"}]}, {"id": "q4", "prompt": "In “These provide food from spring to autumn”, “These” refers to …", "accepted_answers": ["D"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the farmers"}, {"value": "B", "label": "B  the fields"}, {"value": "C", "label": "C  the crop pests"}, {"value": "D", "label": "D  the strips of flowers"}]}, {"id": "q5", "prompt": "In “although they are tested for safety”, “they” refers to …", "accepted_answers": ["B"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the bees"}, {"value": "B", "label": "B  the chemicals"}, {"value": "C", "label": "C  the crops"}, {"value": "D", "label": "D  the researchers"}]}, {"id": "q6", "prompt": "In “it is the combination that matters”, the combination is of …", "accepted_answers": ["A"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the different causes"}, {"value": "B", "label": "B  flowers and insects"}, {"value": "C", "label": "C  chemicals and crops"}, {"value": "D", "label": "D  beekeepers and scientists"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Beekeepers in many countries have reported losing large numbers of honeybees each winter. Scientists have suggested several causes for this. One is a tiny parasite that attaches itself to bees and weakens them. Another is the loss of wild flowers, which means bees have fewer sources of food. Some farmers have responded by planting strips of flowers along the edges of their fields. These provide food from spring to autumn, and they also attract other insects that eat crop pests. A third cause may be the chemicals used to protect crops; although they are tested for safety, their combined effect on bees is less well understood. Researchers say that no single factor explains the losses. Instead, it is the combination that matters.", "teacher_notes": "1 A — “this” = the winter losses.\n2 B — the parasite attaches itself.\n3 C — loss of wild flowers → fewer sources of food.\n4 D — the strips of flowers provide food.\n5 B — the chemicals are tested.\n6 A — no single factor; the combination of causes.\nTeach: replace the word with your answer and read the sentence again.", "focus": "Track reference: identify what pronouns and words such as this, which and these refer to."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'b902c771307caed9cf56d87ea46d22c17988ec4cd126fdf862b59842b211ff5d',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r13-v1','0.1.0','Railway path: track the reference','reading','independent_check','Read the passage. Choose the correct letter, A, B, C or D, for each question. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Look back to the nearest noun or idea that makes sense in place of the word, then check by replacing the word with your answer.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "“The idea” refers to …", "accepted_answers": ["A"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  turning the railway line into a path"}, {"value": "B", "label": "B  building a new road"}, {"value": "C", "label": "C  clearing the bushes"}, {"value": "D", "label": "D  opening a café"}]}, {"id": "q2", "prompt": "In “because it would cost less than building a new road”, “it” refers to …", "accepted_answers": ["C"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the council"}, {"value": "B", "label": "B  the town"}, {"value": "C", "label": "C  the path project"}, {"value": "D", "label": "D  the railway company"}]}, {"id": "q3", "prompt": "In “which had been covered by bushes”, “which” refers to …", "accepted_answers": ["B"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the volunteers"}, {"value": "B", "label": "B  the route"}, {"value": "C", "label": "C  the town"}, {"value": "D", "label": "D  the council"}]}, {"id": "q4", "prompt": "In “Their owners now pay for benches”, “Their” refers to …", "accepted_answers": ["D"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the volunteers’"}, {"value": "B", "label": "B  the cyclists’"}, {"value": "C", "label": "C  the council’s"}, {"value": "D", "label": "D  the local shops’"}]}, {"id": "q5", "prompt": "In “To deal with this”, “this” refers to …", "accepted_answers": ["A"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  some cyclists riding too fast"}, {"value": "B", "label": "B  the narrow path"}, {"value": "C", "label": "C  rising sales"}, {"value": "D", "label": "D  the old station"}]}, {"id": "q6", "prompt": "In “where the path is narrowest”, “where” refers to …", "accepted_answers": ["C"], "taxonomy_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "supporting_node_id": "e75c01d6-b850-4f9e-87bb-f014b7c3947f", "options": [{"value": "A", "label": "A  the shops"}, {"value": "B", "label": "B  the entrance"}, {"value": "C", "label": "C  near the old station"}, {"value": "D", "label": "D  the café"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "In 2015, a disused railway line outside the town was turned into a path for walkers and cyclists. The idea came from a group of residents, and the council supported it because it would cost less than building a new road. Volunteers cleared the route, which had been covered by bushes for decades. When the path opened, local shops near its entrance noticed that their sales rose. Their owners now pay for benches and a small café along the way. However, the path has created one problem: some cyclists ride too fast. To deal with this, the council has put up signs asking them to slow down near the old station, where the path is narrowest.", "teacher_notes": "1 A.\n2 C — the project would cost less than a road.\n3 B — the route had been covered by bushes.\n4 D — the shops’ owners.\n5 A — cyclists riding too fast.\n6 C — near the old station.\nDifferent text from R12; not a calibrated equivalent form.", "focus": "Track reference: identify what pronouns and words such as this, which and these refer to."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'ba2701c4dcb8ebe968f98b24a39f02c69766c2abf98d1a524d5bde390f94120a',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r14-v1','0.1.0','Noisy classrooms: what does each paragraph do?','reading','guided_practice','Read the passage. Choose what each paragraph, A–F, does in the text from the list. There are more choices than paragraphs.','Ask what job each paragraph does in the whole text (background, problem, solution, evidence, result, objection), not what it is about.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph A", "accepted_answers": ["i"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}, {"id": "q2", "prompt": "Paragraph B", "accepted_answers": ["ii"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}, {"id": "q3", "prompt": "Paragraph C", "accepted_answers": ["iii"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}, {"id": "q4", "prompt": "Paragraph D", "accepted_answers": ["iv"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}, {"id": "q5", "prompt": "Paragraph E", "accepted_answers": ["v"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}, {"id": "q6", "prompt": "Paragraph F", "accepted_answers": ["vi"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  gives background"}, {"value": "ii", "label": "ii  describes a problem"}, {"value": "iii", "label": "iii  proposes a solution"}, {"value": "iv", "label": "iv  describes a trial"}, {"value": "v", "label": "v  reports the results"}, {"value": "vi", "label": "vi  raises a reservation"}, {"value": "vii", "label": "vii  compares two countries"}, {"value": "viii", "label": "viii  summarises the whole text"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "A. For decades, schools have been built with hard floors and bare walls, because these are cheap and easy to clean.\n\nB. Such rooms echo, however. Studies of classrooms show that pupils at the back often miss one word in four when the teacher is speaking.\n\nC. One answer is to fit sound-absorbing panels to the ceilings and to put rugs in reading corners.\n\nD. A primary school in a northern city tried this in two classrooms in 2019, while two similar rooms were left unchanged.\n\nE. After a term, teachers in the treated rooms said they spoke less loudly, and pupils’ scores on listening tasks were slightly higher.\n\nF. Critics point out that the study was small and that the panels are expensive, so the results may not justify the cost for every school.", "teacher_notes": "A i background (why rooms are hard and bare).\nB ii problem (echo; missed words).\nC iii solution (panels and rugs).\nD iv trial (two treated rooms, two unchanged).\nE v results.\nF vi reservation (small study, cost).\nvii and viii are distractors: no countries are compared and no paragraph sums up.\nTeach: label each paragraph’s job before reading the options.", "focus": "Recognise text organisation: the function of each paragraph in a problem–solution–evaluation text."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'3fafdf00005983ffe4c0e2235d0417f17b48fce03ee5ff3d352da4e86dc57bac',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r15-v1','0.1.0','Parcel boxes: what does each paragraph do?','reading','independent_check','Read the passage. Choose what each paragraph, A–F, does in the text from the list. There are more choices than paragraphs. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Ask what job each paragraph does in the whole text (background, problem, solution, evidence, result, objection), not what it is about.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph A", "accepted_answers": ["iii"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}, {"id": "q2", "prompt": "Paragraph B", "accepted_answers": ["vii"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}, {"id": "q3", "prompt": "Paragraph C", "accepted_answers": ["vi"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}, {"id": "q4", "prompt": "Paragraph D", "accepted_answers": ["v"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}, {"id": "q5", "prompt": "Paragraph E", "accepted_answers": ["i"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}, {"id": "q6", "prompt": "Paragraph F", "accepted_answers": ["ii"], "taxonomy_node_id": "6820bff3-06df-4ab2-9437-c0da69fa3906", "supporting_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "options": [{"value": "i", "label": "i  reports the results"}, {"value": "ii", "label": "ii  raises a reservation"}, {"value": "iii", "label": "iii  gives background"}, {"value": "iv", "label": "iv  explains why customers prefer large boxes"}, {"value": "v", "label": "v  describes a trial"}, {"value": "vi", "label": "vi  proposes a solution"}, {"value": "vii", "label": "vii  describes a problem"}, {"value": "viii", "label": "viii  gives the history of cardboard"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "A. Online shops send millions of parcels every day, and most of them arrive in cardboard boxes.\n\nB. Many of these boxes are far larger than the items inside, so delivery vans carry a great deal of air and use more fuel than necessary.\n\nC. Some companies now use machines that measure each order and cut a box to fit it exactly.\n\nD. One warehouse tested such a machine for three months on half of its orders.\n\nE. The boxes it produced used 30 per cent less cardboard, and each van could carry more parcels.\n\nF. The machines are costly, however, and smaller sellers say they cannot afford them.", "teacher_notes": "A iii background.\nB vii problem (oversized boxes, wasted fuel).\nC vi solution (made-to-fit boxes).\nD v trial.\nE i results.\nF ii reservation (cost for small sellers).\niv and viii are distractors.\nDifferent text and list order from R14; not a calibrated equivalent form.", "focus": "Recognise text organisation: the function of each paragraph in a problem–solution–evaluation text."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'ec703d9743a618fde214f971b044fabdc1a0f16f287fb357ba3194b0c2f16d88',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r16-v1','0.1.0','Teenage sleep: why does the writer mention it?','reading','guided_practice','Read the passage. Choose the correct letter, A, B, C or D, for each question.','Ask why the writer included this point: to introduce a view, explain, give evidence, admit a problem or conclude.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Why does the writer mention parents’ complaints?", "accepted_answers": ["B"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To show that parents are right"}, {"value": "B", "label": "B  To introduce a common view that the writer will question"}, {"value": "C", "label": "C  To criticise teenagers"}, {"value": "D", "label": "D  To describe a research method"}]}, {"id": "q2", "prompt": "Why does the writer mention melatonin?", "accepted_answers": ["A"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To explain why teenagers feel awake late at night"}, {"value": "B", "label": "B  To recommend a medicine"}, {"value": "C", "label": "C  To compare the diets of children and adults"}, {"value": "D", "label": "D  To show that sleep is unimportant"}]}, {"id": "q3", "prompt": "What is the purpose of the sentence beginning “In other words”?", "accepted_answers": ["C"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To introduce a new topic"}, {"value": "B", "label": "B  To disagree with the research"}, {"value": "C", "label": "C  To restate the scientific point in simple terms"}, {"value": "D", "label": "D  To give an example of a school"}]}, {"id": "q4", "prompt": "Why does the writer mention schools that start at 8.30?", "accepted_answers": ["D"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To show that bus timetables are a problem"}, {"value": "B", "label": "B  To criticise attendance rules"}, {"value": "C", "label": "C  To describe after-school sports"}, {"value": "D", "label": "D  To give evidence that a later start can help"}]}, {"id": "q5", "prompt": "Why does the writer mention bus timetables and after-school sports?", "accepted_answers": ["A"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To admit that a later start has practical difficulties"}, {"value": "B", "label": "B  To argue that schools should start earlier"}, {"value": "C", "label": "C  To give more evidence of the benefits"}, {"value": "D", "label": "D  To change the topic to sport"}]}, {"id": "q6", "prompt": "What is the writer’s main purpose?", "accepted_answers": ["B"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To describe how hormones work"}, {"value": "B", "label": "B  To argue that school times should reflect teenagers’ sleep patterns"}, {"value": "C", "label": "C  To complain about lazy teenagers"}, {"value": "D", "label": "D  To compare schools in different countries"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Many parents complain that their teenage children stay up late and are difficult to wake in the morning. It is easy to see this as laziness, but research suggests another explanation. During adolescence, the body releases the sleep hormone melatonin about two hours later than in childhood. In other words, teenagers are not choosing to feel awake at night; their bodies are. Some schools have moved the start of the school day from 7.30 to 8.30 a.m. In those schools, attendance improved and fewer students fell asleep in class. Of course, a later start creates problems for bus timetables and after-school sports. Even so, the evidence suggests that school times should take teenagers’ biology into account.", "teacher_notes": "1 B — sets up the “laziness” view, then “but research suggests another explanation”.\n2 A.\n3 C — “In other words” restates.\n4 D — evidence: attendance improved.\n5 A — concession “Of course …”.\n6 B — final sentence states the position.\nTeach: purpose verbs — introduce, explain, illustrate, support, concede, conclude.", "focus": "Infer the writer''s purpose: why a detail, example or sentence is included."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'0b5709e60a99e3848a8b6aea9b4caa1f48003ead3dc3c2fec5406303e840139f',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r17-v1','0.1.0','Plastic bags: why does the writer mention it?','reading','independent_check','Read the passage. Choose the correct letter, A, B, C or D, for each question. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Ask why the writer included this point: to introduce a view, explain, give evidence, admit a problem or conclude.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Why does the writer mention people’s predictions?", "accepted_answers": ["C"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To show that the predictions were correct"}, {"value": "B", "label": "B  To explain the price of the bags"}, {"value": "C", "label": "C  To contrast them with what actually happened"}, {"value": "D", "label": "D  To criticise psychologists"}]}, {"id": "q2", "prompt": "Why does the writer compare the charge to “the price of a sweet”?", "accepted_answers": ["A"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To show how small the charge was"}, {"value": "B", "label": "B  To suggest that sweets should be taxed"}, {"value": "C", "label": "C  To show that shoppers bought sweets instead"}, {"value": "D", "label": "D  To show that the charge was unfair"}]}, {"id": "q3", "prompt": "Why does the writer mention psychologists?", "accepted_answers": ["B"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To question the figures"}, {"value": "B", "label": "B  To explain why such a small charge worked"}, {"value": "C", "label": "C  To introduce paper cups"}, {"value": "D", "label": "D  To recommend higher charges"}]}, {"id": "q4", "prompt": "Why does the writer mention paper cups?", "accepted_answers": ["D"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To prove that all charges fail"}, {"value": "B", "label": "B  To praise cafés"}, {"value": "C", "label": "C  To give the price of coffee"}, {"value": "D", "label": "D  To show that a similar charge can have a different effect"}]}, {"id": "q5", "prompt": "Why does the writer say coffee customers are “often in a hurry”?", "accepted_answers": ["A"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To suggest a reason for the smaller effect"}, {"value": "B", "label": "B  To criticise the customers"}, {"value": "C", "label": "C  To recommend faster service"}, {"value": "D", "label": "D  To describe the plastic bag charge"}]}, {"id": "q6", "prompt": "What is the purpose of the last sentence?", "accepted_answers": ["C"], "taxonomy_node_id": "7e4ffe5a-500d-4297-a16b-5b965fb1b705", "supporting_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "options": [{"value": "A", "label": "A  To describe the charge on paper cups"}, {"value": "B", "label": "B  To report what shoppers said"}, {"value": "C", "label": "C  To draw a general lesson from the examples"}, {"value": "D", "label": "D  To introduce a new charge"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "When a small country introduced a charge for plastic bags in shops, many people predicted that shoppers would simply pay it and carry on as before. The charge was very low—about the price of a sweet. Yet within a year, the number of bags used fell by more than 70 per cent. Psychologists point out that people dislike paying for something that used to be free, even when the amount is tiny. Interestingly, a similar charge on paper cups in some cafés had a much smaller effect. One explanation is that customers buying coffee are often in a hurry. Anyone who wants to change people’s behaviour, therefore, should consider not only the size of a charge but also the situation in which people meet it.", "teacher_notes": "1 C — “Yet within a year … fell by more than 70 per cent”.\n2 A.\n3 B.\n4 D — contrast case.\n5 A — “One explanation”.\n6 C — “therefore” draws the conclusion.\nDifferent text from R16; not a calibrated equivalent form.", "focus": "Infer the writer''s purpose: why a detail, example or sentence is included."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'6fc7d79d6caf4d31b6837e387ee0c9e585d90232a90d9e3725b84148ee912255',true) on conflict (code) do nothing;
